// ─── File: src/main/java/com/bank/core/Account.java ───
package com.bank.core;

import java.io.Serializable;
import java.math.BigDecimal;

public class Account implements Serializable {
    // Explicit version stamp — YOU control compatibility.
    private static final long serialVersionUID = 1L;

    private String accountId;
    private String holderName;
    private BigDecimal balance;

    public Account(String accountId, String holderName, BigDecimal balance) {
        this.accountId = accountId;
        this.holderName = holderName;
        this.balance = balance;
    }

    // Adding this method does NOT change serialVersionUID because it is declared.
    public String describe() { return accountId + " / " + holderName; }

    public String getAccountId() { return accountId; }
    public String getHolderName() { return holderName; }
    public BigDecimal getBalance() { return balance; }
}
```

