// ─── File: src/main/java/com/bank/core/VersionUidDemo.java ───
package com.bank.core;

import java.io.*;
import java.math.BigDecimal;
import java.util.logging.*;

public class VersionUidDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        CacheStore store = new CacheStore();
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000.00"));

        byte[] cached = store.serialize(rajesh);
        log.info(() -> "Cached account, bytes = " + cached.length);

        // Compatible reload: same serialVersionUID 1L → succeeds.
        Account reloaded = store.deserialize(cached);
        log.info(() -> "Reloaded OK: " + reloaded.describe()
                        + " balance=" + reloaded.getBalance());

        // Simulate a version mismatch by tampering the class descriptor's UID bytes
        // is complex; instead we explain the guarantee and catch InvalidClassException.
        try {
            Account again = store.deserialize(cached);
            log.info(() -> "Second reload OK (ids match): " + again.getAccountId());
        } catch (InvalidClassException e) {
            log.log(Level.SEVERE, "Version mismatch rejected (safe)", e);
        }
    }
}
```
